window.RP_SESSION={"id":"S-820686cae6d9","messages":[{"id":"RP-II-0045214","time":"2026-02-22T12:26:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"주방에서 겨우 도망쳐 나와서는. 가만히 길드의 다른 의자에 몸을 기대어서 앉습니다. 오늘의 아침은 헬리오스가 해준···. 생선구이였었지요. 빵을 같이 먹었더라면 좋기도 했을 것 같습니다.\n\n불향이 제대로 입혀진 생선구이는 완벽했지만, 곁들여 먹을 게 부족했으니까요. 보드라운 생선 살을 가만히 생각합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045215","time":"2026-02-22T12:27:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"······. 음, 배가 고픕니다. 이리저리 길드 슬쩍 살펴보며 먹을 거리가 있나 살펴보기 시작합니다.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045216","time":"2026-02-22T12:28:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"멀리서 보기에는···. 좀 수상해 보이겠지요.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045217","time":"2026-02-22T12:31:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"길드를 잠시 떠나 헬리오스가 맡긴 일을 처리하던 시간이 1년, 길드에서 생활했던 것도 1년.\n\n짧다면 짧은 시간에 만난 수많은 동료들. 그리고 다시 돌아온 길드에서 마주한 많은 새 동료들.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045218","time":"2026-02-22T12:31:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"············.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045219","time":"2026-02-22T12:31:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"친해지기 너무 무섭습니다······. 말 걸다가 우후죽순으로 모이기 시작할 거라는 게 보여서 두렵습니다······.","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045220","time":"2026-02-22T12:35:00+09:00","room":"RP II","name":"마리우스","profile":"마리우스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b6d81d634c6e"]},{"id":"RP-II-0045221","time":"2026-02-22T12:35:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... to be continue.","characters":[]}]};
